/*
 * ECDSA verification against the RFC 6979 A.2.5 (P-256) and A.2.6 (P-384)
 * test vectors: messages "sample" and "test" hashed with SHA-1, SHA-224,
 * SHA-256, SHA-384 and SHA-512, so the digest is shorter than, as long as, and
 * longer than the group order. Each signature must verify, and must stop
 * verifying when its last byte (the low byte of s) is changed. Every vector
 * was first checked with an independent Python implementation.
 *
 * Build and run from the repository root on an x86_64 host (on an aarch64
 * Linux host add -D__arm64__ so cc_unit is 64-bit):
 *   clang -fsanitize=address,undefined -fno-sanitize-recover=all -w \
 *     -Iinclude $(sed -n '/set(corecrypto_sources/,/^)/p' CMakeLists.txt \
 *     | grep 'src/' | tr -d '\t ' | sort -u) tests/standalone/ecdsa_rfc6979.c \
 *     -o /tmp/ecdsa_rfc6979 && /tmp/ecdsa_rfc6979
 */
#include <corecrypto/ccec.h>
#include <stdbool.h>
