#define CASE(curve, tag) { #curve " " #tag, ccec_cp_##curve, pub_##curve, sizeof(pub_##curve), \
	d_##curve##_##tag, sizeof(d_##curve##_##tag), sig_##curve##_##tag, sizeof(sig_##curve##_##tag) }

static const struct {
	const char* name;
	ccec_const_cp_t (*cp)(void);
	const uint8_t* pub;
	size_t pub_len;
	const uint8_t* digest;
	size_t digest_len;
	const uint8_t* sig;
	size_t sig_len;
} cases[] = {
	CASE(256, sha1_sample),
	CASE(256, sha224_sample),
	CASE(256, sha256_sample),
	CASE(256, sha384_sample),
	CASE(256, sha512_sample),
	CASE(256, sha1_test),
	CASE(256, sha224_test),
	CASE(256, sha256_test),
	CASE(256, sha384_test),
	CASE(256, sha512_test),
	CASE(384, sha1_sample),
	CASE(384, sha224_sample),
	CASE(384, sha256_sample),
	CASE(384, sha384_sample),
	CASE(384, sha512_sample),
	CASE(384, sha1_test),
	CASE(384, sha224_test),
	CASE(384, sha256_test),
	CASE(384, sha384_test),
	CASE(384, sha512_test),
};

/* verify a heap copy of digest and signature so ASan sees over-reads */
static bool verifies(size_t i, bool corrupt) {
	ccec_const_cp_t cp = cases[i].cp();
	ccec_pub_ctx_decl_cp(cp, key);
	if (ccec_import_pub(cp, cases[i].pub_len, cases[i].pub, key) != 0)
		return false;

	uint8_t* digest = malloc(cases[i].digest_len);
	uint8_t* sig = malloc(cases[i].sig_len);
	memcpy(digest, cases[i].digest, cases[i].digest_len);
	memcpy(sig, cases[i].sig, cases[i].sig_len);
	if (corrupt)
		sig[cases[i].sig_len - 1] ^= 0x01;

	bool valid = false;
	int rc = ccec_verify(key, cases[i].digest_len, digest, cases[i].sig_len, sig, &valid);
	free(digest);
	free(sig);
	return rc == 0 && valid;
}

int main(void) {
	int failures = 0;
	size_t count = sizeof(cases) / sizeof(cases[0]);

	for (size_t i = 0; i < count; i++) {
		if (!verifies(i, false)) {
			printf("FAIL %s: valid signature rejected\n", cases[i].name);
			failures++;
		}
		if (verifies(i, true)) {
			printf("FAIL %s: corrupted signature accepted\n", cases[i].name);
			failures++;
		}
	}

	printf("%d failure(s) in %zu vectors\n", failures, 2 * count);
	return failures != 0;
}
